import { io, Socket } from 'socket.io-client';
import { API_HOSTNAME } from '.';

export const SOCKET_CONFIG = {
  url: `http://${API_HOSTNAME}`,
  namespace: '/sniff', // ← Ваш неймспейс из Go-хендлера
  options: {
    path: '/socket.io', // ← Критично: должно совпадать с gin.WrapH(srv)
    transports: ['websocket'] as const,
    reconnection: true,
    reconnectionAttempts: 5,
    reconnectionDelay: 1000,
    timeout: 10000,
    autoConnect: false, // ← Лучше подключаться вручную после получения токена
  }
};

export const createSocket = (token?: string): Socket<ServerToClientEvents, ClientToServerEvents> => {
  return io(`${SOCKET_CONFIG.url}${SOCKET_CONFIG.namespace}`, {
    ...SOCKET_CONFIG.options,
    auth: token ? { token } : undefined,
    query: token ? { token } : undefined, // ← Дублируем для совместимости
  });
};

let _socket: Socket<ServerToClientEvents, ClientToServerEvents> | null = null;

export const getSocket = (token?: string) => {
  if (!_socket || !_socket.connected) {
    _socket = createSocket(token);
  }
  return _socket;
};

export const disconnectSocket = () => {
  if (_socket) {
    _socket.disconnect();
    _socket = null;
  }
};